<template>
  <section class="storage-review">
    <p class="help">{{ t('核对未识别实物在历史账期的商品归属。原始库存历史保持不变；已有历史商品资料沿用当期价格，新商品按凭据补充计费资料。另一人批准后，再到周期结算生成费用。', 'Review product identities for unidentified goods in a historical period. Original stock history is preserved. Existing historical product facts and rates are retained; newly identified products need evidenced billing facts. After another person approves, create charges through Period billing.') }}</p>
    <el-alert v-if="error" :title="error" type="error" show-icon :closable="false" />
    <el-form inline label-position="top" :disabled="busy || blocked" @submit.prevent="load">
      <el-form-item :label="t('复核客户', 'Review client')" required><el-select v-model="query.client" filterable remote :remote-method="lookupClients" :aria-label="t('复核客户', 'Review client')"><el-option v-for="row in clients" :key="row.id" :value="row.id" :label="row.label" /></el-select></el-form-item>
      <el-form-item :label="t('账期开始日期', 'Period start date')" required><el-date-picker v-model="query.from" type="date" value-format="YYYY-MM-DD" :aria-label="t('账期开始日期', 'Period start date')" /></el-form-item>
      <el-form-item :label="t('账期结束日期', 'Period end date')" required><el-date-picker v-model="query.to" type="date" value-format="YYYY-MM-DD" :aria-label="t('账期结束日期', 'Period end date')" /></el-form-item>
      <el-form-item><el-button type="primary" :loading="busy" @click="load">{{ t('读取复核账期', 'Load review period') }}</el-button></el-form-item>
    </el-form>
    <template v-if="period">
      <el-descriptions :column="1" border><el-descriptions-item :label="t('历史收费方式', 'Historical pricing mode')">{{ modeLabel }} · {{ financeOption(period.context.frequency) }} · {{ period.context.client.currency || 'GBP' }}</el-descriptions-item><el-descriptions-item :label="t('复核状态', 'Review status')">{{ statusLabel(review?.status) }}</el-descriptions-item><el-descriptions-item v-if="review" :label="t('提交人 / 批准人', 'Prepared by / approved by')">{{ review.preparedBy }} / {{ review.approvedBy || '—' }}</el-descriptions-item><el-descriptions-item v-if="review?.charge" :label="t('已生成费用编号', 'Posted charge ID')">{{ review.charge }}</el-descriptions-item></el-descriptions>
      <h3>{{ t('当期未识别实物', 'Unidentified goods at period end') }}</h3>
      <el-table :data="period.context.unidentifiedStock" border><el-table-column prop="description" :label="t('实物描述', 'Observed description')" min-width="220" /><el-table-column :label="t('库位', 'Location')" min-width="170"><template #default="{ row }">{{ locationName(row.location) }}</template></el-table-column><el-table-column prop="onhand" :label="t('当时实物数量', 'Historical quantity')" min-width="150" /><el-table-column prop="arrivedAt" :label="t('到仓时间（UTC）', 'Arrival time (UTC)')" min-width="220" /></el-table>
      <el-form label-position="top" :disabled="!editable || busy || blocked" @submit.prevent="preview">
        <h3>{{ t('按凭据分配商品', 'Allocate products from evidence') }}</h3>
        <el-table :data="form.allocations" border>
          <el-table-column :label="t('原实物记录', 'Original arrival')" min-width="230"><template #default="{ row, $index }"><el-select v-model="row.arrival" :aria-label="t('原实物记录', 'Original arrival') + ' ' + ($index + 1)"><el-option v-for="item in period.context.unidentifiedStock" :key="item.id" :value="item.id" :label="item.description + ' · ' + item.onhand" /></el-select></template></el-table-column>
          <el-table-column :label="t('核实商品', 'Verified product')" min-width="240"><template #default="{ row, $index }"><el-select v-model="row.product" filterable remote :remote-method="lookupProducts" :aria-label="t('核实商品', 'Verified product') + ' ' + ($index + 1)" @change="ensureFacts"><el-option v-for="item in productOptions" :key="item.id" :value="item.id" :label="item.sku" /></el-select></template></el-table-column>
          <el-table-column :label="t('分配数量', 'Allocated quantity')" min-width="175"><template #default="{ row, $index }"><el-input-number v-model="row.quantity" :min="1" :max="10000000" :precision="0" :aria-label="t('分配数量', 'Allocated quantity') + ' ' + ($index + 1)" /></template></el-table-column>
          <el-table-column min-width="100"><template #default="{ $index }"><el-button v-if="editable" link type="danger" @click="form.allocations.splice($index, 1)">{{ t('移除', 'Remove') }}</el-button></template></el-table-column>
        </el-table>
        <el-button v-if="editable" class="add-row" :disabled="form.allocations.length >= 2000" @click="form.allocations.push({ arrival: period.context.unidentifiedStock[0]?.id || '', product: '', quantity: 1 })">{{ t('拆分商品数量', 'Split product allocation') }}</el-button>
        <template v-if="missingProducts.length"><h3>{{ t('当期没有记录的商品资料', 'Product facts absent from historical records') }}</h3><p class="help">{{ t('请依据该账期的凭据填写。单价为 0 表示沿用客户当期单价，不代表免费。尺寸单位为厘米，体积单位为立方米。', 'Use evidence applicable to this period. A zero product rate uses the historical client rate; it does not mean free storage. Dimensions are in centimetres and volume in cubic metres.') }}</p>
          <div v-for="product in missingProducts" :key="product" class="fact-fields"><strong>{{ productName(product) }}</strong><div class="form-grid"><el-form-item v-for="key in factKeys" :key="key" :label="factLabel(key)" required><el-input v-model="form.facts[product][key]" inputmode="decimal" :aria-label="productName(product) + ' ' + factLabel(key)" /></el-form-item></div></div>
        </template>
        <div class="form-grid"><el-form-item :label="t('核对凭据', 'Review evidence reference')" required><el-input v-model="form.evidenceReference" maxlength="200" :aria-label="t('核对凭据', 'Review evidence reference')" /></el-form-item><el-form-item :label="t('复核说明', 'Review reason')" required><el-input v-model="form.reason" type="textarea" :rows="2" maxlength="500" :aria-label="t('复核说明', 'Review reason')" /></el-form-item></div>
        <el-button v-if="editable" :loading="busy" type="primary" @click="preview">{{ t('预览复核金额', 'Preview reviewed amount') }}</el-button>
      </el-form>
      <template v-if="displayedQuote"><h3>{{ quote ? t('本次预览', 'Current preview') : t('已保存的复核金额', 'Saved review amount') }}</h3><p>{{ t('服务端合计', 'Server total') }}: {{ displayedQuote.amount }} {{ period.context.client.currency || 'GBP' }}</p><el-table :data="displayedQuote.lines" border><el-table-column :label="t('计费项目', 'Charge item')" min-width="240"><template #default="{ row }">{{ storageLineLabel(row.description) }}</template></el-table-column><el-table-column prop="quantity" :label="t('计费数量', 'Billable quantity')" min-width="130" /><el-table-column prop="rate" :label="t('单价', 'Rate')" min-width="130" /><el-table-column prop="amount" :label="t('金额', 'Amount')" min-width="130" /></el-table></template>
      <div class="actions"><el-button v-if="editable && quote" type="primary" :disabled="blocked || busy" @click="save">{{ t('保存待审核复核', 'Save review for approval') }}</el-button><el-button v-if="canApprove && review?.status === 'DRAFT' && Number(review.preparedBy) !== Number(user.id)" type="primary" :disabled="blocked || busy || dirty" @click="beginDecision('approve')">{{ t('审核并批准', 'Review and approve') }}</el-button><el-button v-if="canApprove && review?.status === 'APPROVED'" type="warning" :disabled="blocked || busy" @click="beginDecision('revoke')">{{ t('撤销未结算批准', 'Revoke unused approval') }}</el-button><el-button v-if="review" :disabled="busy" @click="showHistory">{{ t('查看复核记录', 'View review history') }}</el-button></div>
      <p v-if="review?.status === 'DRAFT' && Number(review.preparedBy) === Number(user.id)" class="help">{{ t('请由另一位有审批权限的人员审核。', 'Another person with approval permission must review this draft.') }}</p>
      <el-form v-if="decision" label-position="top" :disabled="blocked || busy"><el-form-item :label="t('审核意见', 'Approval reason')" required><el-input v-model="decisionReason" type="textarea" maxlength="500" :aria-label="t('审核意见', 'Approval reason')" /></el-form-item><el-button type="primary" @click="decide">{{ decision === 'approve' ? t('确认批准复核', 'Confirm review approval') : t('确认撤销批准', 'Confirm revocation') }}</el-button><el-button @click="decision = ''">{{ t('取消填写', 'Cancel entry') }}</el-button></el-form>
      <template v-if="events.length"><h3>{{ t('复核记录', 'Review history') }}</h3><el-table :data="events" border><el-table-column prop="at" :label="t('时间（UTC）', 'Time (UTC)')" min-width="220" /><el-table-column :label="t('状态', 'Status')" min-width="160"><template #default="{ row }">{{ statusLabel(row.document.status) }}</template></el-table-column><el-table-column prop="actorId" :label="t('操作人编号', 'Actor ID')" min-width="110" /><el-table-column :label="t('说明', 'Reason')" min-width="220"><template #default="{ row }">{{ row.document.decisionReason || row.document.proposal.planInput.reason }}</template></el-table-column></el-table></template>
    </template>
  </section>
</template>
<script setup>
import { computed, ref, watch, onMounted, toRaw } from 'vue'
import { ElMessage } from 'element-plus'
import auth from '@/plugins/auth'
import request from '@/utils/request'
import useUserStore from '@/store/modules/user'
import { bilingual as t, financeOption, storageLineLabel } from '@/warehouse/i18n'
import { getWarehouseLookups } from '@/api/warehouse'
import { financePending, financePendingError, financeBusy, financeRevision, submitFinance } from '@/warehouse/finance'
import { storageFactKeys, storageReviewInput } from '@/warehouse/storage-review'
const user = useUserStore(), base = '/warehouse/finance/storage-reviews'
const query = ref({ client: '', from: '', to: '' }), period = ref(null), review = ref(null), form = ref({ allocations: [], facts: {}, reason: '', evidenceReference: '' }), clients = ref([]), products = ref([]), error = ref(''), busy = ref(false), quote = ref(null), quotedInput = ref(null), loadedForm = ref(''), events = ref([]), decision = ref(''), decisionReason = ref('')
const blocked = computed(() => financeBusy.value || !!financePending.value || !!financePendingError.value), canApprove = computed(() => auth.hasPermi('warehouse:finance:approveStorageReview'))
const editable = computed(() => auth.hasPermi('warehouse:finance:edit') && (!review.value || ['DRAFT', 'REVOKED'].includes(review.value.status)))
const dirty = computed(() => JSON.stringify(form.value) !== loadedForm.value), mode = computed(() => period.value?.context.client.storageType || 'Volumetric'), factKeys = computed(() => storageFactKeys(mode.value))
const modeLabel = computed(() => t(({ StorageUnits: '存储单位', Volumetric: '商品体积', VolumetricCarton: '整箱体积', PerPalletUnit: '托盘单位' })[mode.value] || mode.value, ({ StorageUnits: 'Storage units', Volumetric: 'Product volume', VolumetricCarton: 'Carton volume', PerPalletUnit: 'Pallet units' })[mode.value] || mode.value))
const missingProducts = computed(() => [...new Set(form.value.allocations.map(r => r.product).filter(Boolean))].filter(id => !period.value?.historicalProducts.some(p => p.id === id)))
const productOptions = computed(() => { const rows = new Map(); for (const p of [...(period.value?.historicalProducts || []), ...(review.value?.proposal.productIdentities || []), ...products.value]) rows.set(p.id, p); return [...rows.values()] })
const displayedQuote = computed(() => quote.value?.quote || review.value?.proposal.quote)
const productName = id => productOptions.value.find(p => p.id === id)?.sku || id
const locationName = id => period.value?.context.locations.find(p => p.id === id)?.name || id
const statusLabel = value => t(({ DRAFT: '待审核', APPROVED: '已批准，待周期结算', REVOKED: '已撤销批准', CONSUMED: '已结算' })[value] || '尚未创建复核', ({ DRAFT: 'Awaiting approval', APPROVED: 'Approved, awaiting billing', REVOKED: 'Approval revoked', CONSUMED: 'Billed' })[value] || 'No review yet')
const factLabel = key => t(({ unitStoragePrice: '商品仓储单价', volume: '单件体积（立方米）', unitsPerCarton: '每箱件数', cartonHeight: '箱高（厘米）', cartonLength: '箱长（厘米）', cartonDepth: '箱深（厘米）', unitsPerPallet: '每托件数' })[key], ({ unitStoragePrice: 'Product storage rate', volume: 'Unit volume (m³)', unitsPerCarton: 'Units per carton', cartonHeight: 'Carton height (cm)', cartonLength: 'Carton length (cm)', cartonDepth: 'Carton depth (cm)', unitsPerPallet: 'Units per pallet' })[key])
let generation = 0, clientTicket = 0, productTicket = 0
async function lookupClients(q = '') { const ticket = ++clientTicket; try { const r = await getWarehouseLookups('clients', q); if (ticket === clientTicket) clients.value = r.data } catch (e) { error.value = e.message } }
async function lookupProducts(q = '') { const ticket = ++productTicket; try { const r = await request({ url: base + '/products', params: { client: query.value.client, q } }); if (ticket === productTicket) products.value = r.data.rows } catch (e) { error.value = e.message } }
function ensureFacts() { for (const id of missingProducts.value) if (!form.value.facts[id]) form.value.facts[id] = Object.fromEntries(factKeys.value.map(key => [key, ''])) }
async function load() { if (busy.value || blocked.value) return; if (Object.values(query.value).some(v => !v)) { error.value = t('请选择客户和完整账期。', 'Select a client and complete period.'); return }; const ticket = ++generation; busy.value = true; error.value = ''; quote.value = null; events.value = []; decision.value = ''; try { const r = await request({ url: base + '/context', params: { ...query.value } }); if (ticket !== generation) return; period.value = r.data; review.value = r.data.review; const plan = review.value?.proposal.planInput; form.value = { allocations: plan ? structuredClone(toRaw(plan.allocations)) : r.data.context.unidentifiedStock.map(row => ({ arrival: row.id, product: '', quantity: row.onhand })), facts: Object.fromEntries((plan?.productFacts || []).map(row => [row.product, { ...row }])), reason: plan?.reason || '', evidenceReference: plan?.evidenceReference || '' }; ensureFacts(); loadedForm.value = JSON.stringify(form.value); lookupProducts() } catch (e) { if (ticket === generation) error.value = e.message } finally { if (ticket === generation) busy.value = false } }
async function preview() { if (!editable.value || blocked.value || busy.value) return; error.value = ''; try { const input = { ...query.value, planInput: storageReviewInput(period.value, form.value) }, ticket = ++generation; busy.value = true; const r = await request({ url: base + '/preview', method: 'post', data: input, headers: { repeatSubmit: false } }); if (ticket === generation) { quote.value = r.data; quotedInput.value = input } } catch (e) { error.value = e.response ? e.message : t('请核对实物分配总数、必填凭据和计费资料。', 'Check allocated totals, evidence and billing facts.') } finally { busy.value = false } }
async function save() { if (!quote.value || !quotedInput.value || blocked.value || busy.value) return; const data = { ...structuredClone(toRaw(quotedInput.value)), requestId: crypto.randomUUID(), quoteHash: quote.value.quoteHash, ...(review.value ? { _version: review.value._version } : {}) }; await mutate(base, data, t('保存历史仓储复核', 'Save historical storage review')) }
function beginDecision(action) { decision.value = action; decisionReason.value = '' }
async function decide() { if (!decisionReason.value.trim()) { error.value = t('请填写审核意见。', 'Enter the approval reason.'); return }; await mutate(base + '/' + review.value.id + '/actions', { requestId: crypto.randomUUID(), _version: review.value._version, action: decision.value, reason: decisionReason.value.trim() }, t('历史仓储复核审批', 'Historical storage review approval')) }
async function mutate(url, data, label) { if (blocked.value || busy.value) return; busy.value = true; error.value = ''; try { await submitFinance({ url, data, method: 'post', label }); ElMessage.success(t('操作已完成', 'Operation completed')) } catch (e) { error.value = e.message } finally { busy.value = false; if (!financePending.value) await load() } }
async function showHistory() { try { const r = await request({ url: base + '/' + review.value.id }); events.value = r.data.events } catch (e) { error.value = e.message } }
watch(query, () => { generation++; productTicket++; busy.value = false; period.value = null; review.value = null; products.value = []; quote.value = null; events.value = [] }, { deep: true })
watch(form, () => { quote.value = null; quotedInput.value = null }, { deep: true })
watch(financeRevision, () => { if (!busy.value && period.value) load() })
onMounted(() => lookupClients())
</script>
<style scoped>
.storage-review { min-width: 0; }.help { max-width: 75ch; line-height: 1.65; color: var(--el-text-color-regular); }h3 { font-size: 16px; margin: 24px 0 14px; }.el-alert { margin-bottom: 16px; }.add-row { margin: 12px 0 20px; }.form-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 0 20px; margin-top: 16px; }.fact-fields { margin-top: 20px; }.actions { display: flex; flex-wrap: wrap; gap: 12px; margin: 20px 0; }.actions .el-button { margin-left: 0; }:deep(.el-table .el-select), :deep(.el-table .el-input-number) { width: 100%; }@media(max-width:600px) { .form-grid { grid-template-columns: 1fr; } }
</style>
